import org.objectweb.asm.*;import java.util.*;import java.util.jar.*;
public class AuditShadedKotlin {
 static Map<String,Set<String>> methods=new HashMap<>();static Map<String,List<String>> parents=new HashMap<>();static List<String[]> refs=new ArrayList<>();
 static boolean has(String owner,String sig,Set<String>seen){if(owner.startsWith("java/")){try{Class<?> c=Class.forName(owner.replace('/','.'));for(java.lang.reflect.Method m:c.getMethods())if((m.getName()+Type.getMethodDescriptor(m)).equals(sig))return true;for(java.lang.reflect.Constructor<?> m:c.getDeclaredConstructors())if(("<init>"+Type.getConstructorDescriptor(m)).equals(sig))return true;}catch(Exception e){}}if(!seen.add(owner))return false;if(methods.getOrDefault(owner,Collections.emptySet()).contains(sig))return true;for(String p:parents.getOrDefault(owner,Collections.emptyList()))if(has(p,sig,seen))return true;return false;}
 public static void main(String[]args)throws Exception{try(JarFile z=new JarFile(args[0])){var es=z.entries();while(es.hasMoreElements()){var e=es.nextElement();if(!e.getName().endsWith(".class"))continue;ClassReader r=new ClassReader(z.getInputStream(e));String name=r.getClassName();Set<String> defs=new HashSet<>();methods.put(name,defs);List<String> ps=new ArrayList<>(Arrays.asList(r.getInterfaces()));if(r.getSuperName()!=null)ps.add(r.getSuperName());parents.put(name,ps);r.accept(new ClassVisitor(Opcodes.ASM9){public MethodVisitor visitMethod(int a,String n,String d,String s,String[]ex){defs.add(n+d);return new MethodVisitor(Opcodes.ASM9){public void visitMethodInsn(int op,String o,String n,String d,boolean i){if(o.startsWith("kotlin/"))throw new RuntimeException("Unshaded Kotlin reference in "+name);if(o.startsWith("paradox/music/shaded/kotlin/"))refs.add(new String[]{name,o,n+d});}};}},0);}}
 Set<String> missing=new TreeSet<>();for(String[]ref:refs)if(!has(ref[1],ref[2],new HashSet<>())&&!ref[2].startsWith("toString(")&&!ref[2].startsWith("equals(")&&!ref[2].startsWith("hashCode("))missing.add(String.join(" -> ",ref));System.out.println("Checked shaded Kotlin method references: "+refs.size()+"; unresolved: "+missing.size());for(String m:missing)System.out.println(m);if(!missing.isEmpty())System.exit(1);}
}
